func getCurSymbolByAccount(accs []models.Account, accId string) string {
	acc := slicesutils.Find(accs, func(a models.Account) bool {
		return a.ID == accId
	})
	if acc == nil {
		return models.DfltCurrency.Symbol()
	}
	return acc.Currency.Enum.Symbol()
}

func getCurSymbolByCurrency(curs []models.Currency, curId string) string {
	cur := slicesutils.Find(curs, func(c models.Currency) bool {
		return c.ID == curId
	})
	if cur == nil {
		return models.DfltCurrency.Symbol()
	}
	return cur.Enum.Symbol()
}

func getCurIbanPrefixByCurrency(curs []models.Currency, curId string) string {
	cur := slicesutils.Find(curs, func(c models.Currency) bool {
		return c.ID == curId
	})
	if cur == nil {
		return models.DfltCurrency.IBANPrefix()
	}
	return cur.Enum.IBANPrefix()
}

func getTxKindsForAccounts(accs []models.Account, knds []models.TransactionKind) []models.TransactionKind {
	nknds := knds
	if len(accs) < 2 {
		nknds = slicesutils.Filter(knds, func(k models.TransactionKind) bool { return k.Kind != models.TransferTxKind })
	}
	return nknds
}

func getCategoriesOfKinds(cats []models.Category, kndId string) []models.Category {
	kndsCats := []models.Category{}
	for _, cat := range cats {
		if cat.Kind.ID == kndId {
			kndsCats = append(kndsCats, cat)
		}
	}
	return kndsCats
}
